package com.zekodnix.zaramoney.domain;

import com.zekodnix.zaramoney.domain.enumeration.AuditAction;
import jakarta.persistence.*;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.io.Serializable;
import java.time.Instant;

/**
 * Who did what, when, to what (admin and sensitive actions). Append-only: a DB trigger rejects UPDATE / DELETE.
 * Hand-written entity (not generated by JHipster); written only through {@code AuditService}, read through the admin
 * endpoint {@code GET /api/admin/backoffice/audit}. The actor is stored as a login (no FK), so the trail survives the
 * deletion of a user.
 */
@Entity
@Table(name = "audit_event")
public class AuditEvent implements Serializable {

    private static final long serialVersionUID = 1L;

    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "sequenceGenerator")
    @SequenceGenerator(name = "sequenceGenerator")
    @Column(name = "id")
    private Long id;

    @NotNull
    @Column(name = "occurred_at", nullable = false, updatable = false)
    private Instant occurredAt;

    /** Login of the user who acted; null = system / anonymous (e.g. password reset by e-mail link). */
    @Size(max = 100)
    @Column(name = "actor_login", length = 100, updatable = false)
    private String actorLogin;

    @NotNull
    @Enumerated(EnumType.STRING)
    @Column(name = "action", length = 50, nullable = false, updatable = false)
    private AuditAction action;

    /** e.g. TRANSACTION, BANK_ACCOUNT, USER, USER_DETAILS, DEVICE */
    @Size(max = 50)
    @Column(name = "target_type", length = 50, updatable = false)
    private String targetType;

    /** Business key of the target: transaction reference, account number, login, ... */
    @Size(max = 100)
    @Column(name = "target_id", length = 100, updatable = false)
    private String targetId;

    @Size(max = 2000)
    @Column(name = "details", length = 2000, updatable = false)
    private String details;

    @Size(max = 64)
    @Column(name = "ip", length = 64, updatable = false)
    private String ip;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Instant getOccurredAt() {
        return occurredAt;
    }

    public void setOccurredAt(Instant occurredAt) {
        this.occurredAt = occurredAt;
    }

    public String getActorLogin() {
        return actorLogin;
    }

    public void setActorLogin(String actorLogin) {
        this.actorLogin = actorLogin;
    }

    public AuditAction getAction() {
        return action;
    }

    public void setAction(AuditAction action) {
        this.action = action;
    }

    public String getTargetType() {
        return targetType;
    }

    public void setTargetType(String targetType) {
        this.targetType = targetType;
    }

    public String getTargetId() {
        return targetId;
    }

    public void setTargetId(String targetId) {
        this.targetId = targetId;
    }

    public String getDetails() {
        return details;
    }

    public void setDetails(String details) {
        this.details = details;
    }

    public String getIp() {
        return ip;
    }

    public void setIp(String ip) {
        this.ip = ip;
    }

    @Override
    public boolean equals(Object o) {
        return this == o || (o instanceof AuditEvent other && id != null && id.equals(other.id));
    }

    @Override
    public int hashCode() {
        return getClass().hashCode();
    }

    @Override
    public String toString() {
        return "AuditEvent{id=" + id + ", action=" + action + ", actor=" + actorLogin + ", target=" + targetType + ":" + targetId + "}";
    }
}
